CREATE OR REPLACE FUNCTION public.aka_agent_clear_campaign_runtime_claim_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'đang chạy'
      AND NEW.status = 'tạm dừng'
      AND OLD.runtime_claim_target = 'server'
    THEN
      -- Server run control is DB-first. A pause can commit after the executor's
      -- top-level claim committed but before that response reached the caller.
      -- Preserve the exact ownership tuple so the caller can recover the lost
      -- response, observe the paused status, and release the account only from
      -- its normal safe cleanup boundary.
      NEW.runtime_claim_token := OLD.runtime_claim_token;
      NEW.runtime_claim_target := OLD.runtime_claim_target;
      NEW.runtime_claim_vietnam_date := OLD.runtime_claim_vietnam_date;
      NEW.runtime_claimed_at := OLD.runtime_claimed_at;
    ELSE
      NEW.runtime_claim_token := NULL;
      NEW.runtime_claim_target := NULL;
      NEW.runtime_claim_vietnam_date := NULL;
      NEW.runtime_claimed_at := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_validate_campaign_send_exclusion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.extra_settings->'zaloSendExclusionsByAccountId' IS NOT DISTINCT FROM OLD.extra_settings->'zaloSendExclusionsByAccountId'
 AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id AND NEW.staff_id IS NOT DISTINCT FROM OLD.staff_id AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN RETURN NEW; END IF;
 PERFORM public.aka_agent_internal_validate_send_exclusion_selection(NEW.extra_settings->'zaloSendExclusionsByAccountId',NEW.staff_id,NEW.organization_id,NEW.account_id);
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_campaign_completed_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'hoàn thành' AND OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.completed_at = now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.aka_agent_capture_table_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_new jsonb;
  v_old jsonb;
  v_pk jsonb := '{}'::jsonb;
  v_column text;
BEGIN
  -- No schema is stored. Restrict registration to public tables; in particular,
  -- the private log cannot log itself. No catalog query is needed per row.
  IF TG_TABLE_SCHEMA <> 'public' OR TG_WHEN <> 'AFTER' OR TG_LEVEL <> 'ROW'
     OR TG_OP NOT IN ('INSERT','UPDATE') OR TG_NARGS=0 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid table log trigger configuration';
  END IF;
  v_new := to_jsonb(NEW);
  IF TG_OP='UPDATE' THEN
    v_old := to_jsonb(OLD);
  END IF;
  FOREACH v_column IN ARRAY TG_ARGV LOOP
    IF v_column IS NULL OR NOT (v_new ? v_column) OR v_new->v_column='null'::jsonb THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid table log primary key column';
    END IF;
    v_pk := v_pk || jsonb_build_object(v_column,v_new->v_column);
  END LOOP;
  INSERT INTO private.auto_table_logs(table_name,record_pk,operation,old_data,new_data)
    VALUES (TG_TABLE_NAME,v_pk,TG_OP,v_old,v_new);
  RETURN NULL; -- ignored for AFTER ROW triggers
EXCEPTION WHEN OTHERS THEN
  -- Do not include SQLERRM/DETAIL/row values (they can contain credentials).
  -- Cancellation/assertion failures remain PostgreSQL errors; no retry/queue.
  RAISE WARNING 'auto_table_logs: capture skipped (SQLSTATE %)', SQLSTATE;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_guard_result_catalog_v361()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ids bigint[];
BEGIN
 IF TG_TABLE_NAME='auto_account_action_status_policies' THEN ids:=ARRAY[NEW.status_id];
 ELSIF TG_TABLE_NAME='auto_error' THEN ids:=CASE WHEN NEW.detail_status_id IS NULL THEN NULL ELSE ARRAY[NEW.detail_status_id] END;
 ELSE ids:=NEW.sub_status_ids;
 END IF;
 IF ids IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(ids) i LEFT JOIN public.auto_status s ON s.id=i WHERE s.id IS NULL OR s.component_type<>'campaign_detail') THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='result_status_component_invalid';
 END IF;
 RETURN NEW;
END $function$

